//! The test plan's whole path: the library's kind, a seed, the specimen, the recipe built by the
//! modeller in a project's style (its roles resolved there), the clips generated by the anim
//! library, and the built rig measured against the drawn numbers.

use specula_anim::{AnimSet, Skeleton};
use specula_exemplaria::{expand, library, Roles};
use specula_model::{build, BuildParams, Style};

/// A project's style: its own presets, with `coat` and `claw` named through `roles`, and `eye`
/// a preset of the role's own name.
const STYLE: &str = r##"{ "style": "probe",
  "materials": { "fur": { "color": "#7a6a50" }, "horn": { "color": "#302820" }, "eye": { "color": "#d0a040", "emissive": 0.5 } },
  "roles": { "coat": "fur", "claw": "horn" } }"##;

struct ByStyle<'a>(&'a Style);

impl Roles for ByStyle<'_> {
    fn preset(&self, role: &str, hint: &str) -> Result<String, String> {
        self.0.role(role, Some(hint)).map(str::to_string).map_err(|e| e.to_string())
    }
}

fn dist(a: [f32; 3], b: [f32; 3]) -> f64 {
    (0..3).map(|i| f64::from(a[i] - b[i]) * f64::from(a[i] - b[i])).sum::<f64>().sqrt()
}

#[test]
fn a_box_creature_goes_the_whole_path_at_several_seeds() {
    let style = Style::parse(STYLE).unwrap();
    let entry = library::find("box_creature").expect("in the library");
    let resolved = entry.resolved().unwrap();
    let mut hashes = std::collections::BTreeSet::new();
    for seed in [None, Some(1), Some(7), Some(123_456)] {
        let x = expand(&resolved, seed, &ByStyle(&style), &entry.from()).unwrap();
        assert_eq!(x.roles, [("claw".to_string(), "horn".to_string()), ("coat".into(), "fur".into()), ("eye".into(), "eye".into())]);
        let model = build(&x.recipe, &BuildParams { seed, ..BuildParams::new(&style) }).unwrap_or_else(|e| panic!("{seed:?}: {e}\n{}", x.recipe));
        assert!(hashes.insert(model.hash), "each seed builds its own model");
        let tris = model.lods[0].triangle_count();
        assert!(tris > 0 && tris as u32 <= resolved.kind.levels["near"], "{tris} triangles within the kind's near level");
        let mut used: Vec<&str> = model.materials.iter().map(|(n, _)| n.as_str()).collect();
        used.sort();
        assert_eq!(used, ["eye", "fur", "horn"], "drawn in the project's presets");
        // The rig against the drawn numbers (within 1%: they are written to 0.1 mm).
        let rig = model.rig.as_ref().expect("rigged");
        let bone = |n: &str| rig.bones.iter().find(|b| b.name == n).unwrap_or_else(|| panic!("bone {n}"));
        let s = &x.specimen;
        let leg = dist(bone("thigh_lf").head, bone("shin_lf").tail);
        assert!((leg - s.get("leg_length")).abs() <= 0.01 * s.get("leg_length"), "leg {leg} against {}", s.get("leg_length"));
        let tail = dist(bone("tail").head, bone("tail").tail);
        assert!((tail - s.get("tail_length")).abs() <= 0.01 * s.get("tail_length"), "tail {tail} against {}", s.get("tail_length"));
        let height = f64::from(model.bounds.max[1]);
        let withers = x.facts.iter().find(|f| f.0 == "withers_built").unwrap().1;
        assert!(height >= withers - 1e-3, "the model reaches its withers: {height} against {withers}");
        assert!(f64::from(model.bounds.min[1]).abs() < 1e-3, "it stands on the ground: {}", model.bounds.min[1]);
        // The clips, generated by the anim library on the built rig.
        let anims = x.anims.as_deref().expect("clips");
        let skel = Skeleton::from_rig(rig).unwrap();
        let set = AnimSet::load(anims, skel).unwrap_or_else(|e| panic!("{seed:?}: {e}\n{anims}"));
        let names: Vec<&str> = set.clips().map(|(_, c)| c.name.as_str()).collect();
        assert_eq!(names, ["walk", "trot", "idle"]);
        for (_, c) in set.clips() {
            assert!(c.duration > 0.0 && !c.tracks.is_empty(), "{}: moves", c.name);
        }
        let walk = set.clips().find(|(_, c)| c.name == "walk").unwrap().1;
        // Its stride from the specimen's own hips (Froude 0.25, Alexander and Jayes).
        let want = specula_exemplaria::gaits::cycle(0.25, s.get("leg_length"), true);
        assert!((f64::from(walk.distance) - want.stride).abs() < 1e-3, "stride {} against {}", walk.distance, want.stride);
    }
}

#[test]
fn a_style_without_the_roles_refuses_with_the_nearest_presets() {
    let style = Style::parse(r##"{ "materials": { "stone": { "color": "#8c96a3" }, "soot": { "color": "#202020" }, "sand": { "color": "#c0a070" } } }"##).unwrap();
    let entry = library::find("box_creature").unwrap();
    let e = expand(&entry.resolved().unwrap(), Some(3), &ByStyle(&style), "t").unwrap_err();
    // (The body is written first, in its coat.)
    assert_eq!((e.code, e.path.as_str()), ("role_unresolved", "roles.coat"));
    assert!(e.message.contains("nearest presets by colour: sand, stone, soot"), "{e}");
}

/// Hostile kinds of the test plan that still resolve: the widest spreads, sizes at the plan's
/// edges and exponents at their limits that the reach check lets through.
fn accepted_hostile_kinds() -> Vec<specula_exemplaria::Resolved> {
    let mut out = Vec::new();
    for (sd, mean) in [("0.11", "0.6"), ("0.0", "0.3"), ("0.0", "1.2"), ("0.12", "0.9")] {
        for spread in ["0.0", "0.2", "0.36"] {
            for (exponent, head) in [("-1", "0.1"), ("2", "0.25"), ("3", "0.0"), ("-3", "0.0")] {
                let text = format!(
                    r#"{{"kind": 1, "name": "probe", "plan": "box_creature", "about": "a hostile probe",
                    "size": {{"shoulder_height": {{"mean": {mean}, "sd": {sd}, "unit": "m", "own": "x"}}}},
                    "vary": {{"build": {{"spread": {spread}, "own": "x"}}, "legs": {{"spread": {spread}, "own": "x"}}, "tail": {{"spread": {spread}, "own": "x"}}}},
                    "numbers": {{"leg_length": {{"share": 0.62, "exponent": {exponent}, "own": "x"}}, "head_length": {{"share": 0.36, "spread": {head}, "own": "x"}}}}}}"#
                );
                if let Ok(r) = specula_exemplaria::resolve(&specula_exemplaria::Kind::parse(&text).unwrap(), None) {
                    out.push(r);
                }
            }
        }
    }
    out
}

/// EXEMPLARIA.md, A.11: "at 32 seeds every specimen builds", and no two hash alike. Every kind
/// of the library and every accepted hostile kind, at 32 seeds each: built by the modeller in a
/// project's style, closed (no open edge), within the near level's triangles, standing on the
/// ground. (16 kinds today, 512 builds of a few dozen boxes: 7 to 27 s in the test profile on
/// the development laptop while other lanes built.)
#[test]
fn every_seed_of_an_accepted_kind_builds_closed() {
    let style = Style::parse(STYLE).unwrap();
    let mut kinds: Vec<(String, specula_exemplaria::Resolved)> = library::ENTRIES.iter().map(|e| (e.name().to_string(), e.resolved().unwrap())).collect();
    let hostile = accepted_hostile_kinds();
    assert!(hostile.len() >= 8 && hostile.len() < 48, "{} of 48 hostile kinds accepted: the family holds both", hostile.len());
    kinds.extend(hostile.into_iter().enumerate().map(|(i, r)| (format!("hostile {i}"), r)));
    for (name, r) in &kinds {
        let mut hashes = std::collections::BTreeSet::new();
        for seed in 0..32u64 {
            let seed = seed * 7_919 + 1;
            let x = expand(r, Some(seed), &ByStyle(&style), "t").unwrap_or_else(|e| panic!("{name} seed {seed}: {e}"));
            let model = build(&x.recipe, &BuildParams { seed: Some(seed), ..BuildParams::new(&style) }).unwrap_or_else(|e| panic!("{name} seed {seed}: {e}\n{}", x.recipe));
            assert_eq!(model.open_edges, 0, "{name} seed {seed}: closed");
            assert!(model.lods[0].triangle_count() > 0 && f64::from(model.bounds.min[1]).abs() < 1e-3, "{name} seed {seed}");
            if let Some(near) = r.kind.levels.get("near") {
                assert!(model.lods[0].triangle_count() as u32 <= *near, "{name} seed {seed}: within its near level");
            }
            // (A hostile kind may vary nothing: only the library's entries are held to "no two alike".)
            assert!(hashes.insert(model.hash) || name.starts_with("hostile"), "{name}: seed {seed} builds a model another seed built");
        }
    }
}
